#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct { char *buf; int len; int cap; } StrBuilder;

void sb_init(StrBuilder *sb) {
    sb->cap = 16; sb->len = 0;
    sb->buf = malloc(sb->cap); sb->buf[0] = '\0';
}

void sb_append(StrBuilder *sb, char *s) {
    int slen = strlen(s);
    while (sb->len + slen + 1 > sb->cap) {
        sb->cap *= 2;
        sb->buf = realloc(sb->buf, sb->cap);
    }
    memcpy(sb->buf + sb->len, s, slen);
    sb->len += slen;
    sb->buf[sb->len] = '\0';
}

void sb_free(StrBuilder *sb) { free(sb->buf); sb->buf = NULL; sb->len = sb->cap = 0; }

int main() {
    StrBuilder sb;
    sb_init(&sb);
    sb_append(&sb, "Hello");
    sb_append(&sb, " ");
    sb_append(&sb, "World");
    printf("%s\n", sb.buf);
    sb_free(&sb);
    return 0;
}
